using System.ComponentModel;
using System.Diagnostics;
using System.Text.Json.Nodes;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace PowerShapeMcp;

[McpServerToolType]
public sealed class SolidScaleTools(BridgeSession session)
{
    [McpServerTool(Name="prepare_owned_solid_scale",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
    [Description("Prepare one experimental uniform in-place scale of the only SOLID in an owned copy: WORLD mm/factor1, explicit centre, positive factor 0.01..100 except1. Binds this connection's scale plan and owned document, captures eight source XYZ and freezes ownership/checkpoint/context proofs. No selection, geometry change or save. Separate preparation, execution and verification required; unavailable in read-only mode.")]
    public Task<CallToolResult> Prepare([Description("Passive scalePlanHandle from this connection with explicit factor and WORLD centre.")]string scalePlanHandle,[Description("Fresh owned workingDocumentBindingHandle from this connection.")]string workingDocumentBindingHandle,CancellationToken cancellationToken)=>Run("prepare_owned_solid_scale",new(){["scalePlanHandle"]=scalePlanHandle,["workingDocumentBindingHandle"]=workingDocumentBindingHandle},cancellationToken);
    [McpServerTool(Name="execute_owned_solid_scale",ReadOnly=false,Destructive=true,Idempotent=false,OpenWorld=false)]
    [Description("Scale the prepared owned single SOLID once using the fixed uniform NOKEEP recipe. Consumes its intent and CAD leases before submission; selects this body and clears selection only after all successful phases. No save or activation. A returned recipe remains unverified/fenced until the separate verifier. Never retry, inverse, CANCEL or clear selection automatically after an unknown outcome. Requires approval for the intended owned-copy edit; full server only.")]
    public Task<CallToolResult> Execute([Description("Unconsumed ownedSolidScaleHandle issued by prepare_owned_solid_scale in this connection.")]string ownedSolidScaleHandle,CancellationToken cancellationToken)=>Run("execute_owned_solid_scale",new(){["ownedSolidScaleHandle"]=ownedSolidScaleHandle},cancellationToken);
    [McpServerTool(Name="verify_owned_solid_scale",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
    [Description("Independently verify an original complete thirteen-phase SOLID scale receipt with fresh inspection and active-document handles. Checks ownership/checkpoint/saved files, original source XYZ transformed onto target surfaces within the unchanged bounded document tolerance, bounds/COG/raw area and volume laws. May complete the journal and release only its matching qualified fence. No CAD commands or retry. Sampled membership does not prove persistent face/UV correspondence, full topology or saved/reopened persistence; full server only.")]
    public Task<CallToolResult> Verify([Description("Original native scale execution request ID.")]string executionRequestId,[Description("Exact SHA256 of the immutable original raw execution receipt.")]string executionReceiptSha256,[Description("Fresh candidateDocumentHandle from inspection after command return.")]string candidateDocumentHandle,[Description("Fresh one-use active document handle from a listing after command return.")]string activeDocumentHandle,CancellationToken cancellationToken)=>Run("verify_owned_solid_scale",new(){["executionRequestId"]=executionRequestId,["executionReceiptSha256"]=executionReceiptSha256,["candidateDocumentHandle"]=candidateDocumentHandle,["activeDocumentHandle"]=activeDocumentHandle},cancellationToken);
    async Task<CallToolResult> Run(string name,JsonObject input,CancellationToken ct)
    {
        session.AssertToolAllowed(name);bool gate=false,submitted=false,consumed=false;string? request=null,issued=null;var timer=Stopwatch.StartNew();bool mutate=name=="execute_owned_solid_scale",prepare=name=="prepare_owned_solid_scale";
        CallToolResult Failed(string state,string? code=null){var value=new JsonObject{["state"]=state,["localArtifactsMayExist"]=submitted,["cadMutationMayHaveOccurred"]=submitted&&mutate,["intentConsumed"]=consumed,["retryAllowed"]=false};if(request is not null)value["bridgeRequestId"]=request;if(code is not null)value["errorCode"]=code;return DiagnosticTools.Result(value,true);}
        try{
            gate=await session.ReferenceGate.WaitAsync(session.Options.Timeout,ct);if(!gate)return Failed("queue_timeout_before_submission");ct.ThrowIfCancellationRequested();if(File.Exists(FileArtifacts.FixedPath(session.Options.BridgeRoot,"maintenance.json")))return Failed("maintenance_before_submission");JsonObject args;
            if(prepare)args=session.OwnedScales.PrepareParameters(input["scalePlanHandle"]!.GetValue<string>(),input["workingDocumentBindingHandle"]!.GetValue<string>());
            else if(mutate){args=session.SolidScales.Consume(input["ownedSolidScaleHandle"]!.GetValue<string>(),ct);consumed=true;session.RevokeCadLeases(true);}
            else{_=SolidScaleProof.Execution(session.Options.BridgeRoot,input["executionRequestId"]!.GetValue<string>(),input["executionReceiptSha256"]!.GetValue<string>());args=OwnedExecutionProof.VerificationParameters(input,session.Candidates,session.Documents,true);}
            ct.ThrowIfCancellationRequested();var remaining=session.Options.Timeout-timer.Elapsed;if(remaining<=TimeSpan.Zero)return Failed("queue_timeout_before_submission");submitted=true;var reply=await session.Ipc.SubmitAsync("recipe.prepare",new(){["recipeId"]=name,["parameters"]=args},ct,remaining);request=reply["bridgeRequestId"]?.GetValue<string>();
            if(ct.IsCancellationRequested||timer.Elapsed>=session.Options.Timeout)return Failed("solid_scale_outcome_unknown");
            if(prepare){if(reply["state"]?.GetValue<string>()!="owned_uniform_scale_prepared_observed"||reply["qualificationScope"]?.GetValue<string>()!=SolidScaleProof.Scope)return DiagnosticTools.Result(reply,true);var proof=SolidScaleProof.Preparation(session.Options.BridgeRoot,new(){["ownedScaleId"]=reply["ownedScaleId"]!.DeepClone(),["ownedScaleSha256"]=reply["ownedScaleSha256"]!.DeepClone()});if(!JsonNode.DeepEquals(SolidScaleProof.Raw(session.Options.BridgeRoot,request!).Value,reply))throw new ReferenceRejected("solid_scale_preparation_bytes_differ");var result=session.OwnedScales.Issue(reply,args,input["scalePlanHandle"]!.GetValue<string>(),input["workingDocumentBindingHandle"]!.GetValue<string>());issued=result["ownedScaleHandle"]!.GetValue<string>();session.SolidScales.Pin(issued,proof);result.Remove("ownedScaleHandle");result["ownedSolidScaleHandle"]=issued;if(ct.IsCancellationRequested||timer.Elapsed>=session.Options.Timeout){session.SolidScales.Revoke(issued);return Failed("solid_scale_preparation_outcome_unknown");}return DiagnosticTools.Result(result);}
            if(mutate){if(reply["state"]?.GetValue<string>()!="owned_solid_scale_executed_unverified"){reply["intentConsumed"]=true;reply["retryAllowed"]=false;return DiagnosticTools.Result(reply,true);}reply["executionReceiptSha256"]=SolidScaleProof.CheckedExecution(session.Options.BridgeRoot,reply,args);reply["intentConsumed"]=true;reply["retryAllowed"]=false;return DiagnosticTools.Result(reply);}
            if(reply["state"]?.GetValue<string>()!="owned_solid_scale_verified_observed")return DiagnosticTools.Result(reply,true);SolidScaleProof.CheckedVerification(session.Options.BridgeRoot,reply,args);return DiagnosticTools.Result(reply);
        }
        catch(OperationCanceledException)when(ct.IsCancellationRequested){if(issued is not null)session.SolidScales.Revoke(issued);return Failed(submitted?"solid_scale_outcome_unknown":"cancelled_before_submission");}
        catch(Exception e)when(e is ReferenceRejected or IOException or UnauthorizedAccessException or System.Text.Json.JsonException or InvalidOperationException or KeyNotFoundException or FormatException or NullReferenceException){if(issued is not null)session.SolidScales.Revoke(issued);return Failed(submitted?"solid_scale_outcome_unknown":"solid_scale_rejected_before_submission",e is ReferenceRejected r?r.Code:"solid_scale_proof_unavailable");}
        finally{if(gate)session.ReferenceGate.Release();}
    }
    public static McpServerTool[] Create(BridgeSession s){if(!s.PreparedEnabled("prepare_owned_solid_scale"))return[];var tools=new SolidScaleTools(s);return[new StrictTool(McpServerTool.Create(tools.Prepare),s,SolidQuarterTurnTools.Schema("scalePlanHandle","workingDocumentBindingHandle")),new StrictTool(McpServerTool.Create(tools.Execute),s,SolidQuarterTurnTools.Schema("ownedSolidScaleHandle")),new StrictTool(McpServerTool.Create(tools.Verify),s,SolidQuarterTurnTools.Schema("executionRequestId","executionReceiptSha256","candidateDocumentHandle","activeDocumentHandle"))];}
}
